<script nonce="{{ request()->attributes->get('csp_nonce') }}">
(() => {
    const message = document.getElementById('security-message');
    const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';
    const show = (text, ok = true) => { message.className = `notification ${ok ? 'is-success' : 'is-danger'}`; message.textContent = text; message.scrollIntoView({behavior: 'smooth', block: 'center'}); };
    const api = async (url, method = 'GET', data = undefined, raw = false) => {
        const headers = {'Accept': 'application/json', 'X-CSRF-TOKEN': csrf};
        if (data !== undefined) headers['Content-Type'] = 'application/json';
        const response = await fetch(url, {method, credentials: 'same-origin', headers, body: data === undefined ? undefined : raw ? data : JSON.stringify(data)});
        const result = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(result.message || Object.values(result.errors || {}).flat().join(' ') || 'The request could not be completed.');
        return result;
    };
    const b64bytes = (value) => Uint8Array.from(atob(value.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - value.length % 4) % 4)), c => c.charCodeAt(0));
    const b64url = (value) => btoa(String.fromCharCode(...new Uint8Array(value))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
    const showCodes = (codes) => { const list = document.getElementById('recovery-list'); list.replaceChildren(...codes.map(code => { const item = document.createElement('li'); item.textContent = code; return item; })); document.getElementById('recovery-display').hidden = false; };
    const bindJsonForm = (id, url, body, done) => { const form = document.getElementById(id); if (!form) return; form.addEventListener('submit', async event => { event.preventDefault(); const button = form.querySelector('button[type="submit"]'); button.disabled = true; try { const result = await api(url, 'POST', body()); show(result.message || 'Security setting updated.'); done?.(result); } catch (error) { show(error.message, false); } finally { button.disabled = false; } }); };
    const mfa = document.querySelector('[data-mfa-enabled]');
    const root = '/account/security/actions';
    document.getElementById('mfa-start')?.addEventListener('click', async event => { const button = event.currentTarget; button.disabled = true; try { const result = await api(mfa.dataset.mfaSetup, 'POST', {}); document.getElementById('mfa-secret').textContent = result.secret; document.getElementById('mfa-uri').textContent = result.provisioning_uri; document.getElementById('mfa-pending').hidden = false; } catch (error) { show(error.message, false); button.disabled = false; } });
    bindJsonForm('mfa-confirm-form', mfa.dataset.mfaConfirm, () => ({code: document.getElementById('mfa-confirm-code').value}), result => { showCodes(result.recovery_codes || []); document.getElementById('mfa-state').textContent = 'Two-factor authentication is enabled. Save your recovery codes now.'; document.getElementById('mfa-start')?.remove(); document.getElementById('mfa-pending').hidden = true; });
    bindJsonForm('recovery-form', mfa.dataset.recoveryCodes, () => ({password: document.getElementById('recovery-password').value, code: document.getElementById('recovery-totp').value}), result => showCodes(result.recovery_codes || []));
    bindJsonForm('mfa-disable-form', mfa.dataset.mfaDisable, () => ({password: document.getElementById('disable-password').value, code: document.getElementById('disable-code').value}), () => window.location.reload());
    document.querySelectorAll('.revoke-device').forEach(button => button.addEventListener('click', async () => { if (!confirm('Revoke this trusted device?')) return; try { const result = await api(button.dataset.url, 'DELETE'); show(result.message); window.location.reload(); } catch (error) { show(error.message, false); } }));
    document.getElementById('revoke-all-devices')?.addEventListener('click', async () => { if (!confirm('Revoke all trusted devices?')) return; try { const result = await api(`${root}/devices/revoke-all`, 'POST', {}); show(result.message); window.location.reload(); } catch (error) { show(error.message, false); } });
    document.querySelectorAll('.revoke-passkey').forEach(button => button.addEventListener('click', async () => { if (!confirm('Revoke this passkey?')) return; try { const result = await api(button.dataset.url, 'DELETE'); show(result.message); window.location.reload(); } catch (error) { show(error.message, false); } }));
    document.getElementById('register-passkey')?.addEventListener('click', async event => {
        const button = event.currentTarget; button.disabled = true;
        try {
            if (!window.PublicKeyCredential || !navigator.credentials) throw new Error('This browser does not support passkeys.');
            const options = await api(`${root}/passkeys/registration/options`, 'POST', {});
            const publicKey = options.public_key;
            publicKey.challenge = b64bytes(publicKey.challenge);
            publicKey.user.id = b64bytes(publicKey.user.id);
            (publicKey.excludeCredentials || []).forEach(item => { item.id = b64bytes(item.id); });
            const credential = await navigator.credentials.create({publicKey});
            if (!credential) throw new Error('Passkey registration was cancelled.');
            const payload = {id: credential.id, rawId: b64url(credential.rawId), type: credential.type, response: {attestationObject: b64url(credential.response.attestationObject), clientDataJSON: b64url(credential.response.clientDataJSON), transports: credential.response.getTransports?.() || []}};
            const verifyUrl = `${root}/passkeys/registration/${options.challenge_id}/verify?name=${encodeURIComponent(document.getElementById('passkey-name').value)}`;
            const result = await api(verifyUrl, 'POST', JSON.stringify(payload), true); show(result.message); window.location.reload();
        } catch (error) { show(error.message || 'Passkey registration failed.', false); button.disabled = false; }
    });
})();
</script>
